challenge.verificationSource:
mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("a_prefix=[4,1]; b_prefix=[5,6,1]; shared=[8,4,5]","8"),
        ("a_prefix=[1]; b_prefix=[2]; shared=[9]","9"),
        ("a_prefix=[1]; b_prefix=[1]; shared=[]","none"),
        ("a_prefix=[]; b_prefix=[2]; shared=[7,8]","7"),
        ("a_prefix=[8,4]; b_prefix=[8]; shared=[4,5]","4"),
        ("values=[4,1,8,4,5,5,6,1] next=[1,2,3,4,none,6,7,2] a=0 b=5","8"),
        ("values=[1,1] next=[none,none] a=0 b=1","none"),
        ("values=[3,7,3,9] next=[1,none,3,1] a=0 b=2","7"),
        ("  \na_prefix=[4,1]; b_prefix=[5,6,1]; shared=[8,4,5]\n  ","8"),
        ("\na_prefix=[8,4]; b_prefix=[8]; shared=[4,5]\n","4")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS list-intersection");
}
